import{_ as t,d as o,e as n,x as i}from"./chunks/framework.BRr8VP3a.js";const h=JSON.parse('{"title":"A.11 HV11 Open-Ended Undertaking (Full Interface Card)","description":"","frontmatter":{"title":"A.11 HV11 Open-Ended Undertaking (Full Interface Card)","xkChars":0,"xkWords":1831},"headers":[],"relativePath":"en/theory/appendix-a/a-11.md","filePath":"en/theory/appendix-a/a-11.md"}'),a={name:"en/theory/appendix-a/a-11.md"};function r(s,e,d,c,l,u){return o(),n("div",null,[...e[0]||(e[0]=[i('<div class="theory-source"><h1 id="section-a-11" tabindex="-1"><span class="xk-num"><span class="xk-num__n">A.11</span><span class="xk-num__gap"></span></span>HV11 Open-Ended Undertaking (Full Interface Card) <a class="header-anchor" href="#section-a-11" aria-label="Permalink to &quot;A.11 HV11 Open-Ended Undertaking (Full Interface Card) {#section-a-11}&quot;">​</a></h1><p>A. Identity, Proposition, and Scope</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>Interface ID (<code>id</code>)</td><td>HV11</td></tr><tr><td>Qualified ID (<code>qualified_id</code>)</td><td><code>human_variable:HV11</code></td></tr><tr><td>Name (<code>name</code>)</td><td>Open-Ended Undertaking</td></tr><tr><td>Claim type (<code>claim_type</code>)</td><td>H</td></tr><tr><td>Contract role (<code>contract_role</code>)</td><td><code>human_variable_interface</code></td></tr><tr><td>Proposition (<code>proposition</code>)</td><td>Open-ended undertaking examines only actual costs, voluntariness, direction, alternative explanations, and structural consequences. It does not diagnose whether someone has love.</td></tr><tr><td>Scope (<code>scope</code>)</td><td>Undertaking in human relationships, organizations, institutions, and public action</td></tr><tr><td>Conditions for suspension (<code>pause_condition</code>)</td><td>Suspend naming the action as open-ended undertaking under R1 if voluntariness or the ability to refuse or exit cannot be confirmed safely. R0 may still register candidate actions, costs, coercion risks, gaps in the right to stop, and protection needs. Diagnosing personality or love is always prohibited.</td></tr></tbody></table></div><p>B. Formal Dependencies and Limits on Conclusions</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>Inferential dependencies (<code>inferential_requires</code>)</td><td>None (empty set)</td></tr><tr><td>Protocol dependencies (<code>protocol_requires</code>)</td><td>1. N4<br>2. EVIDENCE<br>3. SOURCE</td></tr><tr><td>Qualification/specialization (<code>specializes</code>)</td><td>1. H6<br>2. H2</td></tr><tr><td>References to applicable objects (<code>applies_to</code>)</td><td>None (empty set)</td></tr><tr><td>Conditional support routes (<code>conditional_support_routes</code>)</td><td>1. route_id=HV11-R0-action-cost-record;<br>claim_level=normative_boundary;<br>when=There are grounds for the action and its costs. Direction, who benefits, and the consequences can each be recorded as known or unknown, but evidence of voluntariness or the ability to refuse or exit is still insufficient;<br>additional_inferential_requires=None (empty set);<br>additional_protocol_requires=None (empty set);<br>allowed_conclusion=Describe candidate undertakings, the distribution of costs, coercion risks, gaps in the right to stop, and protection needs;<br>result_ceiling=Do not call the action open-ended undertaking, diagnose love or personality, or require the person to continue.<br>2. route_id=HV11-R1-voluntary-limited-action;<br>claim_level=normative_boundary;<br>when=There are grounds for the action and its actual costs, its direction is clear, and voluntariness and genuine conditions for refusal, exit, or negotiation receive separate support. Relevant alternative explanations are checked. Record the outcome as realized, unrealized, harmful, or unknown. Structural success is not required for entry;<br>additional_inferential_requires=None (empty set);<br>additional_protocol_requires=None (empty set);<br>allowed_conclusion=Register a description of bounded voluntary undertaking and the outcome status. Failure or an unknown outcome does not cancel supported facts about the action and its voluntariness;<br>result_ceiling=Description of the action only. Do not elevate individual undertaking to a group duty or authorize conscription, protection, or resource arrangements.<br>3. route_id=HV11-R2-structural-consequence;<br>claim_level=conditional_effect;<br>when=An eligible G2-instance shows that the action has an above-threshold effect on the preselected structural outcome through the specified channel;<br>additional_inferential_requires=G2-instance;<br>additional_protocol_requires=CAUSAL, E4;<br>allowed_conclusion=Register the action’s structural consequences within the specified channel, object, and window;<br>result_ceiling=A structural effect does not establish voluntariness, love, goodness, normative justification, unlimited responsibility, or authorization to act. Support for an effect in R2 cannot fill an evidence gap in R1. Coerced action can also have identifiable effects.</td></tr><tr><td>Permitted inferences (<code>allowed_inference</code>)</td><td>1. Description of bounded undertaking and its consequences</td></tr><tr><td>Prohibited leaps (<code>prohibited_leap</code>)</td><td>1. Diagnosing whether someone has love<br>2. Equating sacrifice with love<br>3. Equating responsibility with unlimited undertaking<br>4. Equating refusal with moral failure</td></tr></tbody></table></div><p>C. Nine-Axis Scale and Object Contract</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>Nine-axis scale profile (<code>scale_profile</code>)</td><td>SP=&lt;A,X,T,O,C,R,I,N,J&gt;. A=Aggregation level covers individual acts of undertaking, cases involving actors, populations of relationships or organizations, distributions of costs and voluntariness, and aggregation rules. X=Spatial extent covers sites of relationships and care, organizational boundaries, digital public spaces, and the reach of benefits across domains. T=Time span covers windows for immediate action, sustained undertaking, exhaustion, recovery, and effects across generations. O=Organizational level covers roles in action, relationships or teams, organizations, institutions, and governance ecologies. C=Causal level covers events of undertaking, mechanisms of interaction between actions and costs, meso-level relational structures, institutional arrangements of responsibility, and systemic conditions. R=Resolution covers original actions and costs, sequences of undertaking, cases involving actors, distributions of costs and voluntariness, consequence metrics, and summaries. Record compression loss as well. I=Scope of influence covers direct actors and beneficiaries, dependents, those indirectly taking over, second-order spillovers, and impacts across domains and generations. N=Network topology scope covers dependencies in care, links of benefit, alternative arrangements for taking over, exit paths, and cost networks across domains. J=Scope of jurisdiction and authorization requires separate authorization records for demands to take up work, resource use, refusal, stopping, protection, and remedy. Preserve differences in voluntariness, costs, and exit</td></tr><tr><td>Effective object (<code>effective_object</code>)</td><td>Human arrangements for undertaking in which action, cost, direction, voluntariness, conditions for refusal, and consequences must be examined separately. Judge R0, R1, and R2 under their own conditions without first screening actions by their structural consequences</td></tr><tr><td>Scale invariants (<code>scale_invariants</code>)</td><td>1. Costs, voluntariness, direction, alternative explanations, consequences, and rights to stop</td></tr><tr><td>Required additions for scale elevation (<code>required_scale_additions</code>)</td><td>1. Distribution of voluntariness<br>2. Relations of representation<br>3. Cost spillovers<br>4. A genuine means of exit and protection provided through representatives</td></tr><tr><td>What changes with scale (<code>changing_semantics</code>)</td><td>1. Forms of undertaking, positions bearing costs, and beneficiaries can change</td></tr><tr><td>Inapplicable objects (<code>non_applicable_objects</code>)</td><td>1. Nonhuman systems without intentionality, voluntariness, responsibility, or the capability for meaning</td></tr><tr><td>Prohibited elevations (<code>forbidden_elevation</code>)</td><td>1. Elevating individual undertaking to a group duty<br>2. Transferring the concept of human undertaking into the nonhuman core</td></tr></tbody></table></div><p>D. State, Evidence, and Variable Flows</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>State set (<code>state</code>)</td><td>1. Candidate<br>2. Voluntary and bounded<br>3. Risk of coercion<br>4. Unilateral exhaustion<br>5. Stopping or exit</td></tr><tr><td>Observables (<code>observables</code>)</td><td>1. Time and resources invested, opportunities forgone, and bodily and psychological costs of the action<br>2. Whether refusal, exit, stopping, and renegotiation are genuinely available<br>3. Direction of the action, positions receiving benefits, and detectable structural consequences<br>4. Alternative explanations such as coercion, fear, dependence, interests, and acting for show</td></tr><tr><td>Evidence requirements (<code>evidence</code>)</td><td>1. Actions and costs<br>2. Conditions for refusal and exit<br>3. Alternative explanations<br>4. Benefits and consequences</td></tr><tr><td>Input dependencies and interface content (<code>input_dependencies</code>)</td><td>1. Orientation anchor<br>2. Uptake layer<br>3. Conditional potential field<br>4. Power and safety</td></tr><tr><td>Output effects and variable flows (<code>output_effects</code>)</td><td>1. Distribution of costs<br>2. States of relationships and institutions<br>3. Stopping and repair</td></tr><tr><td>Time window and lag (<code>time_window_and_lag</code>)</td><td>Register immediate costs, sustained undertaking, exhaustion, and recovery lags</td></tr><tr><td>Uncertainty (<code>uncertainty</code>)</td><td>Record dependence, fear, hidden coercion, and safety of expression</td></tr><tr><td>Local exclusion zone (<code>local_exclusion_zone</code>)</td><td>Positions where people cannot refuse safely, cannot exit, or are masked by moral pressure</td></tr><tr><td>Affected positions (<code>affected_positions</code>)</td><td>1. Actors<br>2. Beneficiaries<br>3. Dependents<br>4. People taking over</td></tr></tbody></table></div><p>E. Uptake, Responsibility, Normative Status, Ceilings, and Correction</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>Uptake carriers (<code>carrier</code>)</td><td>1. Specific actors<br>2. Relational practices<br>3. Arrangements for care or responsibility</td></tr><tr><td>Responsible parties (<code>responsible_subject</code>)</td><td>1. Those making demands<br>2. Parties granting authorization<br>3. Parties responsible as beneficiaries<br>4. Parties responsible for remedy</td></tr><tr><td>Normative status (<code>normative_status</code>)</td><td>Subject to N4. It cannot be commanded or conscripted</td></tr><tr><td>Judgment ceiling (<code>judgment_ceiling</code>)</td><td>Apply the limits for R0, R1, and R2 separately. R0 describes only costs, direction, risks, and candidate actions. With corresponding evidence, R1 describes the action’s voluntariness and conditions for refusal and exit. R2 judges structural consequences within a limited scope only if the corresponding G2 and causal conditions hold. No level may diagnose personality, prove love or goodness, infer a duty to undertake, or authorize real-world action. Ethical naming is separately subject to the normative premises of GOV-14. Reaching R2 does not satisfy that requirement.</td></tr><tr><td>Action ceiling (<code>action_ceiling</code>)</td><td>This variable produces only descriptions of voluntariness, actual costs, direction, alternative explanations, structural consequences, and needs for stopping and protection. It does not authorize protective measures, demands to take up work, requisition of resources, or adjudication of personality. Any real-world adjustment separately requires C12, explicit N premises at runtime, J authorization, and O procedures</td></tr><tr><td>Counterexamples (<code>counterexamples</code>)</td><td>1. One-sided sacrifice that cannot be refused is praised as love or responsibility<br>2. A claim of undertaking lacks evidence of the stated action or cost. Actual failed attempts and unknown outcomes are recorded separately. Their action descriptions must not be categorically withdrawn for lack of structural success</td></tr><tr><td>Appeal (<code>appeal</code>)</td><td>Under <code>appeal_and_rollback_rule</code>, actors can refuse to be represented and report coercion, costs, alternative explanations, and restrictions on exit through a safe, accessible channel with anti-retaliation protection. This triggers review independent of the original judgment or chain of demands concerning the undertaking</td></tr><tr><td>Rollback (<code>rollback</code>)</td><td>Under <code>appeal_and_rollback_rule</code>, once rollback is authorized, the designated responsible party must within the stated deadline revoke the undertaking designation and related demands and actually restore the conditions of refusal and exit and the state of records and resources. Preserve versions and verification of completion</td></tr></tbody></table></div><p><code>scale_profile</code> is the complete nine-axis record SP=&lt;A,X,T,O,C,R,I,N,J&gt;. A single “micro–macro” label cannot stand in for it. A is aggregation level, which must declare units, population, distribution, and aggregation rules. X covers physical space and digital boundaries. T covers windows, lags, and cycles. O is organizational level across roles, teams, organizations, institutions, and governance ecologies. C is causal level across events, interaction mechanisms, meso-level structures, institutions, and systemic conditions. R is resolution across original events, sequences, individual cases, distributions, metrics, and summaries, with compression loss recorded. I is the scope of direct, indirect, second-order, cross-domain, and intergenerational impacts. N is network topology scope. J is scope of jurisdiction and authorization. Expanding A, X, O, or I does not automatically expand J. Observing more cannot confer greater authority to act.</p><p>Recorded identities and the object’s identity criterion belong to K in the object contract. Relationships and channels of effect belong in <code>input_dependencies</code>, <code>carrier</code>, or the causal contract. Membership and affected positions belong in <code>affected_positions</code>, <code>local_exclusion_zone</code>, and observation fields. None may substitute for a scale axis. The N scale axis is network topology. Below, “explicit N premises at runtime” refers to N1–N5 in the normative choice layer. The two must not be conflated.</p><p>All 11 variables share the same limit on action. The variables themselves produce only descriptions, evidence gaps, and requirements for action. They do not authorize real-world adjustments. Their output ceilings are as follows.</p><div class="xk-table"><table><thead><tr><th>Variable</th><th>Descriptions or Needs This Variable Can Produce</th></tr></thead><tbody><tr><td>HV01</td><td>Candidate structural domains, boundary disputes, and needs for more evidence</td></tr><tr><td>HV02</td><td>Boundary states, interface barriers, exclusion risks, and testing needs</td></tr><tr><td>HV03</td><td>Candidate anchors, diverse expressions, comparison results, and needs for more evidence</td></tr><tr><td>HV04</td><td>Candidate classifications for GC, GS, and GE, state transitions, and needs for more evidence</td></tr><tr><td>HV05</td><td>CV, RS, costs, capacity, rights to stop, gaps in uptake, and needs to reduce load, add resources, or reallocate them</td></tr><tr><td>HV06</td><td>Chain connectivity, time lags, losses, interruptions, costs, and uptake needs</td></tr><tr><td>HV07</td><td>Intake, changes to record fields, execution, duration, gaps in write-back, and needs for procedural repair</td></tr><tr><td>HV08</td><td>Candidate channels through which conditions could have effects, differences across positions, masking of evidence, and needs to reduce risk</td></tr><tr><td>HV09</td><td>Load, capacity, recovery, local overload, and needs to reduce load or add resources</td></tr><tr><td>HV10</td><td>Component applicability, prototype matches, and mixed states under the selected route, limited explanations of phase mechanisms or historical conditional increments, independent X0 path status, uncertainty, and observation needs</td></tr><tr><td>HV11</td><td>Voluntariness, actual costs, direction, alternative explanations, structural consequences, and needs for stopping and protection</td></tr></tbody></table></div><p>However obvious the need may seem, any real-world adjustment separately requires C12, explicit N premises at runtime, J authorization, and O procedures. The variables must not authorize testing, load reduction, adding resources, repair, protection, attribution of responsibility, exploratory action, advancement, exit arrangements, or other action on their own.</p></div>',1)])])}const f=t(a,[["render",r]]);export{h as __pageData,f as default};
